mutation AcknowledgeAllDeadLetters($note: String!) {
  operations {
    deadLetters {
      acknowledgeAllDeadLetters(note: $note) {
        count
        message
      }
    }
  }
}

mutation AcknowledgeDeadLetter($id: Long!, $note: String!) {
  operations {
    deadLetters {
      acknowledgeDeadLetter(id: $id, note: $note) {
        success
        message
