  }
}

query Attention {
  operations {
    attention {
      asOf
      scheduler {
        manifestManagerEnabled
        jobDispatcherEnabled
        paused
        link
      }
      deadLetters {
        trainName
        reason
        count
        oldestDeadLetteredAt
        link
      }
      failingTrains {
        trainName
        failedLastHour
        finishedLastHour
        lastHourFailureRate
        baselineFailureRate
        link
      }
      stuckInstances {
        machine
        state
        count
        link
      }
      queue {
        queued
        oldestQueuedAt
        oldestAgeSeconds
        link
      }
      offlineHosts {
        instanceId
        hostName
        lastHeartbeatAt
        runsDispatcher
        link
      }
    }
  }
}

query BulkOperation($id: UUID!, $failuresAfter: Long, $failuresTake: Int! = 100) {
  operations {
    bulkOperation(id: $id) {
      id
      kind
      status
      actor
      askAfresh
      startedAt
      finishedAt
      total
      done
      failed
      message
      filter {
        executions {
          trainState
          trainName
          startedAfter
          startedBefore
          manifestId
          manifestGroupId
          hideAdminTrains
          failureClass
          externalId
          parentId
          hostName
          failureReasonContains
          failureJunction
        }
        deadLetters {
          status
          manifestId
        }
        manifests {
          isEnabled
          scheduleType
          nameContains
          manifestGroupId
          hideAdminTrains
        }
      }
      failureReasons {
        reason
        count
      }
      failures(take: $failuresTake, afterId: $failuresAfter) {
        id
        reason
      }
    }
  }
}

