        items {
          id
          externalId
          trainName
          status
          createdAt
          dispatchedAt
          priority
          dispatchAttempts
          manifestId
          metadataId
          subjectKey
          confirmedAt
          replayDecisionsOf
        }
        totalCount
        isEstimatedCount
        nextCursor
      }
    }
  }
}
